mapper.select:
SELECT b.id AS block_id, b.blocked_member_id AS peer_id,
       COALESCE(NULLIF(m.nickname, ''), NULLIF(m.name, ''), CONCAT('用户', b.blocked_member_id)) AS nickname
  FROM im_block b
  LEFT JOIN ums_member m ON m.id = b.blocked_member_id
 WHERE b.member_id = #{viewer} AND b.blocked_member_id <> #{viewer}
   AND b.id < #{cursor}
 ORDER BY b.id DESC
 LIMIT #{limit}
